#!/usr/bin/env bash

set -o nounset
set -Eeuo pipefail
set -o errexit

test "${DEBUG:-0}" = 0 || set -o xtrace

is_tty() {
    [ -t 1 ] && [ -r /dev/tty ] && [ -w /dev/tty ]
}

ATOMIC_DIR=""
TEMP_DIR=""
PYTHON_CMD=""
UI_CLI_SCRIPT=""
INSTALLATION_CANCELLED=0
MILESTONE_LOGS=""

if [ -z "${NO_UI:-}" ]; then
    is_tty && NO_UI=0 || NO_UI=1
fi
if [ -z "${NO_CLEAR:-}" ]; then
    [ "${DEBUG:-0}" -eq 0 ] && is_tty && NO_CLEAR=0 || NO_CLEAR=1
fi
OVERWRITE_INSTALL_DIR=${OVERWRITE_INSTALL_DIR:-0}
export TEXTUAL_THEME="${TEXTUAL_THEME:-gruvbox}"
if [ -n "${NO_COLOR+set}" ]; then
    NO_COLOR_ACTIVE=1
else
    NO_COLOR_ACTIVE=0
fi

################################################################################
# PYTHON & TEXTUAL BOOTSTRAP LOGIC
################################################################################

ensure_ui() {
    [ "${NO_UI}" -eq 1 ] && return 1

    if ! command -v python3 > /dev/null 2>&1; then
        echo "Python3 not found. Falling back to text mode." >&2
        return 1
    fi

    local VULN_CHECK_CODE="
import sys, json, urllib.request
url = 'https://pypi.org/pypi/textual/6.8.0/json'
try:
    with urllib.request.urlopen(url, timeout=5) as response:
        data = json.loads(response.read().decode())
        vulns = data.get('vulnerabilities', [])
        if len(vulns) > 0:
            print(f'VULNERABILITIES_FOUND: {len(vulns)}')
            sys.exit(1)
except Exception:
    pass
"
    if ! python3 -c "$VULN_CHECK_CODE"; then
        echo "Security Check Failed: Vulnerabilities detected in textual 6.8.0." >&2
        return 1
    fi

    if [ -z "${TEMP_DIR}" ]; then
        TEMP_DIR=$(mktemp -d)
    fi

    local WHEEL_PATH="${TEMP_DIR}/textual-6.8.0-py3-none-any.whl"
    echo "$TEXTUAL_WHEEL_BASE64" | base64 -d > "$WHEEL_PATH" 2> /dev/null || true

    printf "Initializing temp Python virtual environment...  " >&2
    python3 -m venv "${TEMP_DIR}/venv" > /dev/null 2>&1 &
    local pid=$!
    local spin='-\|/'
    local i=0
    while kill -0 $pid 2> /dev/null; do
        i=$(((i + 1) % 4))
        printf "\b%s" "${spin:i:1}" >&2
        sleep .1
    done
    wait $pid || {
        printf "\bFailed.\n" >&2
        echo "Failed to create venv." >&2
        return 1
    }
    printf "\bDone.\n" >&2

    local PIP_CMD="${TEMP_DIR}/venv/bin/pip"
    PYTHON_CMD="${TEMP_DIR}/venv/bin/python"

    if ! "$PIP_CMD" install "$WHEEL_PATH" --quiet --disable-pip-version-check; then
        echo "Failed to install textual wheel. Falling back to text mode." >&2
        return 1
    fi

    UI_CLI_SCRIPT="${TEMP_DIR}/sep_ui_cli.py"
    cat << 'EOF' > "$UI_CLI_SCRIPT"
import sys
import subprocess
import argparse
import json
import time
import shlex
import shutil
import os
import gzip
import base64
import signal
from rich.console import Console
from rich.panel import Panel
from rich.prompt import Prompt, Confirm
from rich.status import Status
from rich.markdown import Markdown

from textual.app import App, ComposeResult
from textual.widgets import Label, Footer, DataTable, SelectionList, Input, Button
from textual.widgets.selection_list import Selection
from textual.containers import Vertical, Horizontal
from textual.binding import Binding
from textual.screen import ModalScreen
from textual.message import Message

console = Console()

def handle_sigint(signum, frame):
    raise KeyboardInterrupt

signal.signal(signal.SIGINT, handle_sigint)

def cmd_log(args):
    style = "white"
    if args.level == "info": style = "green"
    elif args.level == "warn": style = "yellow"
    elif args.level == "error": style = "red bold"

    prefix = f"[{style}]{args.level.upper()}[/{style}]"
    console.print(f"{prefix} {args.message}")

def cmd_banner(args):
    console.print(Panel(f"[bold {args.color}]SEP INSTALLER[/]", expand=False, border_style=args.color, padding=(1, 2)))

def cmd_spin(args):
    title = args.title
    cmd = args.cmd
    show_error = args.show_error

    status = Status(title, console=console, spinner=args.spinner)
    status.start()
    try:
        cmd_list = shlex.split(cmd)
        result = subprocess.run(cmd_list, capture_output=True, text=True, shell=False)
        status.stop()

        if result.returncode == 0:
            console.print(f"[green]✓[/] {title}")
            sys.exit(0)
        else:
            if show_error:
                console.print(f"[red]✗[/] {title}")
                console.print(Panel(f"[bold red]Command Failed![/]\n[yellow]Command:[/]{cmd}\n\n[bold]Output:[/]\n{result.stdout}\n{result.stderr}", border_style="red"))
            pass
            sys.exit(1)
    except KeyboardInterrupt:
        status.stop()
        sys.exit(130)
    except Exception as e:
        status.stop()
        if show_error:
            console.print(f"[bold red]Error executing command: {e}[/]")
        sys.exit(1)

def cmd_input(args):
    try:
        default = args.default if args.default else ...
        val = Prompt.ask(args.prompt, default=default, password=args.password, console=console)
        if args.output:
            with open(args.output, "w") as f: f.write(val)
        else: print(val)
    except KeyboardInterrupt:
        sys.exit(130)

def cmd_confirm(args):
    try:
        default_bool = True
        if args.default_val and args.default_val.lower() == 'n': default_bool = False
        res = Confirm.ask(args.prompt, default=default_bool, console=console)
        sys.exit(0 if res else 1)
    except KeyboardInterrupt:
        sys.exit(130)

def cmd_print_md(args):
    md = Markdown(args.content)
    console.print(md)

def cmd_console_print(args):
    kwargs = vars(args)
    kwargs.pop("command")
    console.print(*kwargs.pop("content"), **kwargs)

def cmd_success_msg(args):
    content = args.content
    console.print(Panel("[bold green]Installation Complete[/]", border_style="green", expand=False))
    console.print("")
    console.print(Markdown(content))

def cmd_check_prereqs(args):
    tools = args.tools.split()
    missing = []
    with console.status("[bold green]Checking System Requirements..."):
        for tool in tools:
            tool = tool.strip()
            if not shutil.which(tool):
                missing.append(tool)
            time.sleep(0.1)
    if missing:
        console.print(f"[bold red]Missing required tools: {', '.join(missing)}")
        sys.exit(1)

def cmd_mkdir(args):
    path = args.path
    try:
        os.makedirs(path, exist_ok=True)
    except Exception as e:
        console.print(f"[bold red]Failed to create directory {path}: {e}")
        sys.exit(1)

def cmd_generate_tls(args):
    install_dir = args.install_dir
    cert_list = args.cert_list.split(',')

    certs_dir = os.path.join(install_dir, "certs")
    os.makedirs(certs_dir, exist_ok=True)
    cwd = os.getcwd()
    os.chdir(certs_dir)

    def run_openssl_stdout(cmd_list):
        res = subprocess.run(cmd_list, capture_output=True, text=True, shell=False)
        if res.returncode != 0: raise Exception(f"OpenSSL failed: {res.stderr}")
        return res.stdout

    def write_file(filename, content):
        with open(filename, "w") as f: f.write(content)

    with console.status("[bold green]Generating TLS Certificates...") as status:
        try:
            key_content = run_openssl_stdout(["openssl", "genpkey", "-algorithm", "RSA", "-pkeyopt", "rsa_keygen_bits:4096"])
            write_file("sep_token_jwt_key.key", key_content)
            pub_content = run_openssl_stdout(["openssl", "rsa", "-pubout", "-in", "sep_token_jwt_key.key"])
            write_file("sep_token_jwt_key.pem", pub_content)
            ca_key_content = run_openssl_stdout(["openssl", "ecparam", "-genkey", "-name", "secp384r1", "-noout"])
            write_file("sep-ca-key.pem", ca_key_content)
            ca_cert_content = run_openssl_stdout(["openssl", "req", "-new", "-x509", "-key", "sep-ca-key.pem", "-nodes",
                                         "-sha384", "-days", "365", "-subj", "/CN=SEP Root CA",
                                         "-addext", "keyUsage=critical,digitalSignature,keyCertSign",
                                         "-addext", "basicConstraints=critical,CA:true,pathlen:0",
                                         "-addext", "subjectKeyIdentifier=hash",
                                         "-addext", "authorityKeyIdentifier=keyid:always",
                                         "-addext", "extendedKeyUsage=serverAuth,clientAuth"])
            write_file("sep-ca.pem", ca_cert_content)

            base_conf = """[ req ]
distinguished_name = req_distinguished_name
req_extensions = v3_req
[ req_distinguished_name ]
[ v3_req ]
authorityKeyIdentifier = keyid:always,issuer
basicConstraints = critical,CA:FALSE
keyUsage = critical, digitalSignature, keyEncipherment
extendedKeyUsage = serverAuth, clientAuth
subjectAltName = @alt_names
[alt_names]
DNS.1=localhost
DNS.2=sep
DNS.3=*.sep
DNS.4=inventory_api
DNS.5=tasks_api
DNS.6=app
IP.1=127.0.0.1
"""
            for cert in cert_list:
                cert = cert.strip()
                write_file("openssl.conf", base_conf)
                cert_key_content = run_openssl_stdout(["openssl", "ecparam", "-genkey", "-name", "secp384r1", "-noout"])
                write_file(f"{cert}-cert-key.pem", cert_key_content)
                csr_content = run_openssl_stdout(["openssl", "req", "-new", "-key", f"{cert}-cert-key.pem", "-subj", f"/CN={cert}"])
                write_file(f"{cert}-cert.csr", csr_content)
                cert_content = run_openssl_stdout(["openssl", "x509", "-req", "-in", f"{cert}-cert.csr", "-CA", "sep-ca.pem", "-CAkey", "sep-ca-key.pem",
                                             "-CAcreateserial", "-days", "365", "-sha384",
                                             "-extfile", "openssl.conf", "-extensions", "v3_req"])
                write_file(f"{cert}-cert.pem", cert_content)
                if os.path.exists(f"{cert}-cert.csr"): os.remove(f"{cert}-cert.csr")
                if os.path.exists("openssl.conf"): os.remove("openssl.conf")

            for root, dirs, files in os.walk(certs_dir):
                for momo in files: os.chmod(os.path.join(root, momo), 0o444)
        except Exception as e:
            console.print(f"[bold red]Error generating certs: {e}")
            sys.exit(1)
    console.print("[green]✓[/] TLS Certificates generated.")

def strip_marker(content, marker, keep):
    lines = content.splitlines()
    marker_count = sum(1 for line in lines if line.strip() == marker)
    if marker_count % 2 != 0:
        raise SystemExit(f"Unbalanced marker block: {marker}")

    if keep:
        return "\n".join(line for line in lines if line.strip() != marker)

    kept = []
    in_block = False
    for line in lines:
        if line.strip() == marker:
            in_block = not in_block
            continue
        if not in_block:
            kept.append(line)

    return "\n".join(kept)

def cmd_render_templates(args):
    install_dir = args.install_dir
    create_pmm = os.environ.get("CREATE_PMM_CONTAINER", "0") == "1"
    serve_frontend = os.environ.get("SEP_SERVE_FRONTEND", "1") == "1"
    files_map = [("CASDOOR_INIT_JSON_DATA", "casdoor_init.json"), ("NGINX_CONFIG", "nginx.conf"), ("SEP_COMPOSE_YAML", "compose.yaml"), ("SEP_SETTINGS_YAML", "settings.yaml")]
    replacements = {
        "${SEP_HTTP_PORT}": os.environ.get("SEP_HTTP_PORT", ""),
        "${SEP_HTTPS_PORT}": os.environ.get("SEP_HTTPS_PORT", ""),
        "${INSTALL_DIR}": os.environ.get("FINAL_INSTALL_DIR", install_dir),
        "${SEP_PMM_PUBLIC_HOST}": os.environ.get("SEP_PMM_PUBLIC_HOST", ""),
        "${SEP_PMM_PUBLIC_ADDRESS}": os.environ.get("SEP_PMM_PUBLIC_HOST", ""),
        "${SEP_PMM_PORT}": os.environ.get("SEP_PMM_PORT", ""),
        "${SEP_PMM_FRONTEND}": os.environ.get("SEP_PMM_FRONTEND", ""),
        "${SEP_PMM_URL_AUTH_TOKEN}": os.environ.get("SEP_PMM_URL_AUTH_TOKEN", ""),
        "${SEP_PMM_URL_AUTH_ACCOUNT}": os.environ.get("SEP_PMM_URL_AUTH_ACCOUNT", ""),
        "${SEP_IMAGE_NAME}": os.environ.get("SEP_IMAGE_NAME", ""),
        "${SEP_IMAGE_TAG}": os.environ.get("SEP_IMAGE_TAG", ""),
        "${CASDOOR_SEP_CLIENT_ID}": os.environ.get("CASDOOR_SEP_CLIENT_ID", ""),
        "${CASDOOR_SEP_CLIENT_SECRET}": os.environ.get("CASDOOR_SEP_CLIENT_SECRET", ""),
        "${SEP_BACKEND_DB_PASSWORD}": os.environ.get("SEP_BACKEND_DB_PASSWORD", ""),
        "${SEP_REDIS_PASSWORD}": os.environ.get("SEP_REDIS_PASSWORD", ""),
        "${CASDOOR_DEFAULT_ORG_SALT}": os.environ.get("CASDOOR_DEFAULT_ORG_SALT", ""),
        "${CASDOOR_SEP_ORG_SALT}": os.environ.get("CASDOOR_SEP_ORG_SALT", ""),
        "${CASDOOR_DEFAULT_CLIENT_SECRET}": os.environ.get("CASDOOR_DEFAULT_CLIENT_SECRET", ""),
        "${CASDOOR_DEFAULT_CLIENT_ID}": os.environ.get("CASDOOR_DEFAULT_CLIENT_ID", ""),
        "${CASDOOR_DEFAULT_ADMIN_PASSWD}": os.environ.get("CASDOOR_DEFAULT_ADMIN_PASSWD", ""),
        "${CASDOOR_SEP_ADMIN_PASSWD}": os.environ.get("CASDOOR_SEP_ADMIN_PASSWD", ""),
        "${CASDOOR_SEP_SEP_PASSWD}": os.environ.get("CASDOOR_SEP_SEP_PASSWD", ""),
        "${SEP_CASDOOR_CERTIFICATE_JSON}": os.environ.get("SEP_CASDOOR_CERTIFICATE_JSON", "").replace("\\\\n", "\\n"),
        "${SEP_CASDOOR_PRIVATE_KEY_JSON}": os.environ.get("SEP_CASDOOR_PRIVATE_KEY_JSON", "").replace("\\\\n", "\\n"),
        "${SEP_PLUGINS_SCHEMA_CHANGE_DISABLE}": os.environ.get("SEP_PLUGINS_SCHEMA_CHANGE_DISABLE", ""),
        "${SEP_PLUGINS_ARCHIVE_DISABLE}": os.environ.get("SEP_PLUGINS_ARCHIVE_DISABLE", ""),
        "${SEP_PLUGINS_MYSQL_BACKUPS_DISABLE}": os.environ.get("SEP_PLUGINS_MYSQL_BACKUPS_DISABLE", ""),
        "${SEP_PLUGINS_CHECKSUMS_DISABLE}": os.environ.get("SEP_PLUGINS_CHECKSUMS_DISABLE", ""),
        "${SEP_PLUGINS_SNIPPETS_DISABLE}": os.environ.get("SEP_PLUGINS_SNIPPETS_DISABLE", ""),
        "${SEP_PLUGINS_MONGODB_BACKUPS_DISABLE}": os.environ.get("SEP_PLUGINS_MONGODB_BACKUPS_DISABLE", ""),
        "${SEP_PLUGINS_BACKUP_PG_DISABLE}": os.environ.get("SEP_PLUGINS_BACKUP_PG_DISABLE", ""),
        "${SEP_PLUGINS_DIPPER_DISABLE}": os.environ.get("SEP_PLUGINS_DIPPER_DISABLE", ""),
        "${SEP_PLUGINS_ALERTS_DISABLE}": os.environ.get("SEP_PLUGINS_ALERTS_DISABLE", ""),
        "${SEP_PLUGINS_ALERT_TROUBLESHOOTING_DISABLE}": os.environ.get("SEP_PLUGINS_ALERT_TROUBLESHOOTING_DISABLE", ""),
        "${SEP_PLUGINS_REPORT_DISABLE}": os.environ.get("SEP_PLUGINS_REPORT_DISABLE", ""),
        "${SEP_INTERNAL_TOKEN}": os.environ.get("SEP_INTERNAL_TOKEN", ""),
    }
    with console.status("[bold green]Rendering templates...", spinner="point") as status:
        for env_var_name, filename in files_map:
            compressed_data = os.environ.get(env_var_name)
            if not compressed_data: continue
            try:
                decoded = base64.b64decode(compressed_data)
                content = gzip.decompress(decoded).decode('utf-8')
            except Exception as e:
                console.print(f"[red]Error decompressing {filename}: {e}")
                sys.exit(1)
            for key, val in replacements.items():
                content = content.replace(key, val)
            content = strip_marker(content, "#---PMM---#", create_pmm)
            content = strip_marker(content, "#---FRONTEND---#", serve_frontend)
            content = strip_marker(content, "#---NO-FRONTEND---#", not serve_frontend)
            if any(line.strip() in ("#---PMM---#", "#---FRONTEND---#", "#---NO-FRONTEND---#") for line in content.splitlines()):
                raise SystemExit(f"Template rendering left unprocessed marker lines in {filename}")
            out_path = os.path.join(install_dir, filename)
            with open(out_path, "w") as f: f.write(content)
    console.print("[green]✓[/] Templates rendered.")

class ConfirmSelectionList(SelectionList):
    BINDINGS = [
        Binding("enter", "submit_selection", "Confirm", show=True),
        Binding("space", "select_and_next", "Select", show=True),
        Binding("ctrl+a", "toggle_all", "All", show=True),
        Binding("x", "select_no_move", "Toggle", show=True),
        Binding("tab", "cursor_down", "", show=False),
    ]
    class Submitted(Message):
        def __init__(self, selected) -> None:
            self.selected = selected
            super().__init__()
    def action_submit_selection(self): self.post_message(self.Submitted(self.selected))
    def action_select_and_next(self):
        if self.highlighted is not None:
            item = self.get_option_at_index(self.highlighted)
            self.toggle(item.value)
            self.action_cursor_down()
    def action_select_no_move(self):
        if self.highlighted is not None:
            item = self.get_option_at_index(self.highlighted)
            self.toggle(item.value)
    def action_toggle_all(self):
        if len(self.selected) == len(self.options): self.deselect_all()
        else: self.select_all()

class PluginSelectScreen(ModalScreen):
    CSS = """
    PluginSelectScreen { align: center middle; background: $surface 50%; }
    #plugin-container { width: 60; height: auto; border: thick $accent; background: $surface; padding: 0 1; }
    #plugin-header { width: 100%; content-align: center middle; text-style: bold; margin-bottom: 1; background: $primary; color: $text; }
    ConfirmSelectionList { height: 14; border: none; }
    """
    BINDINGS = [
        Binding("escape", "quit_app", "Cancel", show=True),
        Binding("q", "quit_app", "Cancel", show=True),
        Binding("ctrl+c", "quit_app", "Cancel", show=False),
    ]
    PLUGIN_MAPPING = { "Schema Change": "schema_change", "Archive": "archive", "MySQL Backups": "mysql_backups", "Checksums": "checksums", "Collect Diagnostic Data (Snippets)": "snippets", "MongoDB Backups": "mongodb_backups", "PostgreSQL Backups": "backup_pg", "Dipper Data Collection": "dipper", "Alert Templates": "alerts", "Alert Troubleshooting": "alert_troubleshooting", "Health & Security Report": "report" }
    def __init__(self, current_plugins_str, *, confirm_cancel=True):
        super().__init__()
        self.current_selection = [p.strip() for p in current_plugins_str.split(",") if p.strip()]
        self.confirm_cancel = confirm_cancel
    def compose(self):
        with Vertical(id="plugin-container"):
            yield Label("Select Plugins", id="plugin-header")
            selections = []
            for label, value in self.PLUGIN_MAPPING.items():
                is_checked = value in self.current_selection
                selections.append(Selection(label, value, is_checked))
            yield ConfirmSelectionList(*selections)
            yield Footer()
    def on_mount(self): self.query_one(ConfirmSelectionList).focus()
    def on_confirm_selection_list_submitted(self, message): self.dismiss(",".join(message.selected))
    def action_quit_app(self):
        if not self.confirm_cancel:
            self.dismiss(None)
            return
        def cancel_cb(quit_confirmed):
            if quit_confirmed: self.dismiss(None)

        self.app.push_screen(CancelConfirmScreen(), cancel_cb)

class EditSettingScreen(ModalScreen):
    CSS = """
    EditSettingScreen { align: center middle; background: $surface 50%; }
    #edit-dialog { width: 60; height: auto; border: thick $accent; background: $surface; padding: 1 2; }
    #edit-dialog Label { width: 100%; content-align: center middle; margin-bottom: 1; }
    #edit-dialog Input { width: 100%; margin-bottom: 1; }
    .help { color: $text-muted; }
    """
    BINDINGS = [
        Binding("escape", "cancel", "Cancel", show=True),
        Binding("ctrl+c", "cancel", "Cancel", show=True),
    ]
    def __init__(self, setting_name, current_value, default_value, restrict=None):
        super().__init__()
        self.setting_name = setting_name
        self.current_value = current_value
        self.default_value = default_value
        self.restrict = restrict
    def compose(self):
        with Vertical(id="edit-dialog"):
            yield Label(f"Edit {self.setting_name}")
            yield Input(value=self.current_value, placeholder=f"Default: {self.default_value}", restrict=self.restrict)
            yield Label("Enter: Save | Esc: Cancel", classes="help")
    def on_mount(self): self.query_one(Input).focus()
    def on_input_submitted(self, event):
        final_value = event.value.strip()
        if not final_value: final_value = self.default_value
        self.dismiss(final_value)
    def action_cancel(self): self.dismiss(None)

class ConfirmationScreen(ModalScreen):
    CSS = """
    ConfirmationScreen { align: center middle; background: $surface 50%; }
    #confirm-dialog { width: 40; height: auto; border: thick $success; background: $surface; padding: 1 2; }
    #confirm-label { width: 100%; content-align: center middle; margin-bottom: 2; text-style: bold; }
    #confirm-buttons { align: center middle; height: auto; }
    Button { margin: 0 2; }
    """
    BINDINGS = [
        Binding("left", "focus_yes", "Yes", show=False),
        Binding("right", "focus_no", "No", show=False),
        Binding("y", "submit_yes", "Yes", show=True),
        Binding("n", "submit_no", "No", show=True),
        Binding("q", "submit_no", "No", show=False),
        Binding("escape", "submit_no", "No", show=False),
        Binding("ctrl+c", "submit_no", "No", show=False),
    ]
    def compose(self):
        with Vertical(id="confirm-dialog"):
            yield Label("Confirm Settings and Submit?", id="confirm-label")
            with Horizontal(id="confirm-buttons"):
                yield Button("Yes", variant="success", id="yes")
                yield Button("No", variant="error", id="no")
        yield Footer()
    def on_mount(self): self.query_one("#yes").focus()
    def on_button_pressed(self, event): self.dismiss(event.button.id == "yes")
    def action_focus_yes(self): self.query_one("#yes").focus()
    def action_focus_no(self): self.query_one("#no").focus()
    def action_submit_yes(self): self.dismiss(True)
    def action_submit_no(self): self.dismiss(False)

class ConfigTable(DataTable):
    BINDINGS = [
        Binding("e", "select_cursor", "Edit Value", show=True),
        Binding("space", "select_cursor", "Edit Value", show=False),
        Binding("enter", "pass", "Submit", show=True),
    ]

class ConfigApp(App):
    ENABLE_COMMAND_PALETTE = False
    CSS = """
    Screen { align: center middle; }
    #main-container { width: auto; height: auto; align: center middle; }
    #app-title { width: 100%; content-align: center middle; text-style: bold; color: $text; padding-top: 1; padding-bottom: 2; color: $accent; }
    ConfigTable { width: auto; height: auto; border: solid $accent; }
    """
    BINDINGS = [
        Binding("enter", "request_confirmation", "Submit", show=True),
        Binding("q", "quit_app", "Cancel", show=True),
        Binding("escape", "quit_app", "Cancel", show=False),
        Binding("ctrl+c", "quit_app", "Cancel", show=False),
    ]
    def __init__(self, initial_config, theme_name=None):
        super().__init__()
        self.defaults = initial_config.copy()
        self.config_data = initial_config
        if theme_name: self.theme = theme_name
    def compose(self):
        with Vertical(id="main-container"):
            yield Label("Configuration Summary", id="app-title")
            yield ConfigTable(cursor_type="row")
        yield Footer()
    def on_mount(self):
        table = self.query_one(ConfigTable)
        table.add_column("Setting", width=20, key="Setting")
        table.add_column("Value", width=60, key="Value")
        for key, value in self.config_data.items(): table.add_row(key, value, key=key)
        table.focus()
    def on_data_table_row_selected(self, event):
        row_key = event.row_key.value
        current_val = self.config_data[row_key]
        default_val = self.defaults.get(row_key, "")
        table = self.query_one(ConfigTable)
        def update_callback(new_value):
            if new_value is not None:
                self.config_data[row_key] = new_value
                table.update_cell(row_key, "Value", new_value)
        if row_key == "Create PMM":
            new_val = "No" if current_val == "Yes" else "Yes"
            self.config_data["Create PMM"] = new_val
            table.update_cell("Create PMM", "Value", new_val)
        elif row_key == "Plugins":
            self.push_screen(PluginSelectScreen(current_val, confirm_cancel=False), update_callback)
        else:
            self.push_screen(EditSettingScreen(row_key, current_val, default_val, restrict=r"[0-9]*" if "Port" in row_key else None), update_callback)
    def action_request_confirmation(self):
        def confirm_callback(confirmed):
            if confirmed: self.exit(self.config_data)
        self.push_screen(ConfirmationScreen(), confirm_callback)
    def action_quit_app(self):
        def cancel_cb(quit_confirmed):
            if quit_confirmed: self.exit(return_code=130)
        self.push_screen(CancelConfirmScreen(), cancel_cb)

class CancelConfirmScreen(ModalScreen):
    CSS = """
    CancelConfirmScreen { align: center middle; background: $surface 50%; }
    #dialog { width: 40; height: auto; border: thick $error; background: $surface; padding: 1 2; }
    #msg { width: 100%; content-align: center middle; margin-bottom: 2; text-style: bold; }
    #btns { align: center middle; height: auto; }
    Button { margin: 0 2; }
    """
    BINDINGS = [
        Binding("left", "focus_yes", "Yes", show=False),
        Binding("right", "focus_no", "No", show=False),
        Binding("y", "submit_yes", "Yes", show=True),
        Binding("n", "submit_no", "No", show=True),
        Binding("q", "submit_no", "No", show=False),
        Binding("escape", "submit_no", "No", show=False),
        Binding("ctrl+c", "submit_yes", "Yes", show=False),
    ]
    def compose(self):
        with Vertical(id="dialog"):
            yield Label("Cancel Installation?", id="msg")
            with Horizontal(id="btns"):
                yield Button("Yes", variant="error", id="yes")
                yield Button("No", variant="primary", id="no")
    def on_button_pressed(self, event): self.dismiss(event.button.id == "yes")
    def action_focus_yes(self): self.query_one("#yes").focus()
    def action_focus_no(self): self.query_one("#no").focus()
    def action_submit_yes(self): self.dismiss(True)
    def action_submit_no(self): self.dismiss(False)

def cmd_choose_plugins(args):
    class StandalonePluginApp(App):
        def compose(self): yield Label("")
        def on_mount(self):
            def cb(res):
                if res is None:
                    sys.exit(130)
                else:
                    with open(args.output, "w") as f: f.write(res)
                    self.exit()
            self.push_screen(PluginSelectScreen(args.current), cb)
    StandalonePluginApp().run()

def cmd_summary(args):
    data = json.loads(args.data)
    flat_data = {item['key']: str(item['value']) for item in data}
    app = ConfigApp(flat_data)
    result = app.run()
    if not result: sys.exit(130)
    with open(args.output, "w") as f:
        f.writelines([
            f"INSTALL_DIR=\"{result.get('Install Dir', '')}\"\n",
            f"CREATE_PMM_CONTAINER=\"{1 if result.get('Create PMM') == 'Yes' else 0}\"\n",
            f"SEP_ENABLED_PLUGINS=\"{result.get('Plugins', '')}\"\n",
            f"SEP_HTTP_PORT=\"{result.get('HTTP Port', '8080')}\"\n",
            f"SEP_HTTPS_PORT=\"{result.get('HTTPS Port', '8444')}\"\n",
        ])

def main():
    parser = argparse.ArgumentParser()
    subparsers = parser.add_subparsers(dest="command")

    # Args definitions
    p_log = subparsers.add_parser("log")
    p_log.add_argument("--level", default="info")
    p_log.add_argument("message")

    p_banner = subparsers.add_parser("banner")
    p_banner.add_argument("--color", default="magenta")

    p_spin = subparsers.add_parser("spin")
    p_spin.add_argument("--spinner", default="dots")
    p_spin.add_argument("--title")
    p_spin.add_argument("--show-error", action="store_true")
    p_spin.add_argument("cmd")

    p_in = subparsers.add_parser("input")
    p_in.add_argument("--prompt"); p_in.add_argument("--default"); p_in.add_argument("--password", action="store_true"); p_in.add_argument("--output")

    p_conf = subparsers.add_parser("confirm")
    p_conf.add_argument("prompt"); p_conf.add_argument("--default-val")

    p_ch = subparsers.add_parser("choose_plugins")
    p_ch.add_argument("--current"); p_ch.add_argument("--options"); p_ch.add_argument("--output")

    p_sum = subparsers.add_parser("summary")
    p_sum.add_argument("--data"); p_sum.add_argument("--output", required=True)

    subparsers.add_parser("print_md").add_argument("content")

    p_style = subparsers.add_parser("console_print")
    p_style.add_argument("content", nargs="+")
    p_style.add_argument("--style")
    p_style.add_argument("--justify")
    p_style.add_argument("--overflow")
    p_style.add_argument("--sep", default=" ")
    p_style.add_argument("--end", default="\n")
    p_style.add_argument("--no-wrap", action="store_true", default=None)
    p_style.add_argument("--emoji", action="store_true", default=None)
    p_style.add_argument("--markup", action="store_true", default=None)
    p_style.add_argument("--highlight", action="store_true", default=None)
    p_style.add_argument("--soft-wrap", action="store_true", default=None)
    p_style.add_argument("--new-line-start", action="store_true", default=False)
    p_style.add_argument("--no-crop", action="store_false", dest="crop", default=True)
    p_style.add_argument("--width", type=int, default=None)
    p_style.add_argument("--height", type=int, default=None)

    subparsers.add_parser("success_msg").add_argument("content")
    subparsers.add_parser("check_prereqs").add_argument("--tools")
    subparsers.add_parser("mkdir").add_argument("--path")

    p_tls = subparsers.add_parser("generate_tls")
    p_tls.add_argument("--install-dir"); p_tls.add_argument("--cert-list")

    subparsers.add_parser("render_templates").add_argument("--install-dir")

    args, _ = parser.parse_known_args()

    if args.command == "log": cmd_log(args)
    elif args.command == "banner": cmd_banner(args)
    elif args.command == "spin": cmd_spin(args)
    elif args.command == "input": cmd_input(args)
    elif args.command == "confirm": cmd_confirm(args)
    elif args.command == "choose_plugins": cmd_choose_plugins(args)
    elif args.command == "summary": cmd_summary(args)
    elif args.command == "print_md": cmd_print_md(args)
    elif args.command == "console_print": cmd_console_print(args)
    elif args.command == "success_msg": cmd_success_msg(args)
    elif args.command == "check_prereqs": cmd_check_prereqs(args)
    elif args.command == "mkdir": cmd_mkdir(args)
    elif args.command == "generate_tls": cmd_generate_tls(args)
    elif args.command == "render_templates": cmd_render_templates(args)

if __name__ == "__main__":
    main()
EOF

    return 0
}

run_ui() {
    "$PYTHON_CMD" "$UI_CLI_SCRIPT" "$@"
}

################################################################################
# LOGGING HELPERS
################################################################################

log_milestone() {
    local msg="$1"
    if [ "${NO_COLOR_ACTIVE}" -eq 1 ] || [ "${NO_UI}" -eq 1 ]; then
        MILESTONE_LOGS+=$'\n* '"$msg"
    else
        MILESTONE_LOGS+=$'\n[green]✓[/] '"$msg"
    fi

    log_info "$msg"
}

log_info() {
    if [ "${NO_UI}" -eq 0 ]; then
        run_ui log --level info "$1"
    else
        echo "[INFO] $1"
    fi
}

log_err() {
    if [ "${NO_UI}" -eq 0 ] && [ -n "${PYTHON_CMD}" ] && [ -f "${PYTHON_CMD}" ]; then
        run_ui log --level error "$1"
    else
        echo "[ERROR] $1" >&2
    fi
}

log_warn() {
    if [ "${NO_UI}" -eq 0 ]; then
        run_ui log --level warn "$1"
    else
        echo "[WARN] $1" >&2
    fi
}

separator() {
    printf '\n%s\n' "------------------------------------------------------------"
}

clear_screen() {
    [ "${NO_CLEAR}" -eq 1 ] || ! is_tty && separator && return 0
    [ "${NO_COLOR_ACTIVE}" -eq 1 ] && separator && return 0

    if command -v tput > /dev/null 2>&1; then
        tput clear && return 0
    fi

    if command -v clear > /dev/null 2>&1; then
        clear && return 0
    fi

    printf '\033[2J\033[H'
}

banner() {
    clear_screen
    if [ "${NO_UI}" -eq 0 ]; then
        run_ui banner --color "magenta"
    else
        echo "================================================================================"
        echo "                                SEP INSTALLER                                   "
        echo "================================================================================"
        echo ""
    fi
}

cleanup() {
    if [ "${INSTALLATION_CANCELLED:-0}" -eq 1 ]; then
        log_err "Installation Cancelled."
    fi
    if [ -n "${ATOMIC_DIR:-}" ] && [ -d "${ATOMIC_DIR}" ]; then
        rm -rf "${ATOMIC_DIR}"
    fi
    if [ -n "${TEMP_DIR:-}" ] && [ -d "${TEMP_DIR}" ]; then
        rm -rf "${TEMP_DIR}"
    fi
    trap - SIGINT EXIT
}

exit_cleanup() {
    local exit_code=$?
    [ "${exit_code}" -eq 0 ] && return
    [ "${exit_code}" -eq 130 ] && INSTALLATION_CANCELLED=1
    cleanup
    exit "${exit_code}"
}

trap 'exit_cleanup' SIGINT EXIT

spin_or_die() {
    local spinner="$1"
    local title="$2"
    shift 2
    local cmd="$*"

    if [ "${NO_UI}" -eq 0 ]; then
        run_ui spin --spinner "${spinner}" --title "${title}" --show-error "${cmd}"
    else
        echo ">> ${title}"
        if ! output=$(bash -c "${cmd}" 2>&1); then
            log_err "Command Failed: ${cmd}"
            [ -n "${output}" ] && echo "${output}" >&2
            exit 1
        fi
    fi
}

print_styled() {
    local content="$1"
    shift
    if [ "${NO_UI}" -eq 0 ]; then
        run_ui console_print "${content}" "$@"
    else
        echo "${content}"
    fi
}

check_cmd_silent() {
    local cmd="$1"
    if [ "${NO_UI}" -eq 0 ]; then
        run_ui spin --spinner "dots" --title "Checking..." "${cmd}"
    else
        bash -c "${cmd}" > /dev/null 2>&1
    fi
}

################################################################################
# CONFIGURATION & DEFAULTS
################################################################################
CONTAINER_ENGINE="${CONTAINER_ENGINE:-docker}"
CREATE_PMM_CONTAINER="${CREATE_PMM_CONTAINER:-0}"
DEFAULT_CONTAINER_REGISTRY="${CONTAINER_REGISTRY:-docker.io}"
INSTALL_DIR="${INSTALL_DIR:-"${HOME}/sep"}"
SEP_IMAGE_NAME="${SEP_IMAGE_NAME:-${DEFAULT_CONTAINER_REGISTRY}/percona/percona-sep}"
SEP_IMAGE_TAG="${SEP_IMAGE_TAG:-latest}"
SEP_SERVE_FRONTEND="${SEP_SERVE_FRONTEND:-1}"
SEP_HTTP_PORT="${SEP_HTTP_PORT:-8080}"
SEP_HTTPS_PORT="${SEP_HTTPS_PORT:-8444}"
SEP_PMM_PUBLIC_HOST="${SEP_PMM_PUBLIC_HOST:-127.0.0.1}"
SEP_PMM_PORT="${SEP_PMM_PORT:-8443}"
SEP_PMM_FRONTEND="${SEP_PMM_FRONTEND:-https://${SEP_PMM_PUBLIC_HOST}}"
SEP_PMM_NOMAD_DATA_DIR="${SEP_PMM_NOMAD_DATA_DIR:-${INSTALL_DIR}/nomad_data}"
SEP_PMM_CONTAINER_NAME="${SEP_PMM_CONTAINER_NAME:-sep-pmm-1}"
SEP_PMM_URL_AUTH_ACCOUNT_USER="${SEP_PMM_URL_AUTH_ACCOUNT_USER:-}"
SEP_PMM_URL_AUTH_ACCOUNT_PASS="${SEP_PMM_URL_AUTH_ACCOUNT_PASS:-}"
if [[ (-z ${SEP_PMM_URL_AUTH_ACCOUNT_USER} || -z ${SEP_PMM_URL_AUTH_ACCOUNT_PASS}) && -n ${SEP_PMM_URL_AUTH_ACCOUNT:-} ]]; then
    SEP_PMM_URL_AUTH_ACCOUNT_USER="${SEP_PMM_URL_AUTH_ACCOUNT%%:*}"
    SEP_PMM_URL_AUTH_ACCOUNT_PASS="${SEP_PMM_URL_AUTH_ACCOUNT#*:}"
fi
DOCKER_TOKEN="${DOCKER_TOKEN:-}"
CERTLIST="${CERTLIST:-all-in-one}"
RESET_DATA="${RESET_DATA:-0}"

PLUGIN_DISP_SCHEMA="Schema Change"
PLUGIN_DISP_ARCHIVE="Archive"
PLUGIN_DISP_BACKUPS="MySQL Backups"
PLUGIN_DISP_CHECKSUMS="Checksums"
PLUGIN_DISP_SNIPPETS="Collect Diagnostic Data (Snippets)"
PLUGIN_DISP_MONGO="MongoDB Backups"
PLUGIN_DISP_BACKUP_PG="PostgreSQL Backups"
PLUGIN_DISP_DIPPER="Dipper Data Collection"
PLUGIN_DISP_ALERTS="Alert Templates"
PLUGIN_DISP_ALERT_TROUBLESHOOTING="Alert Troubleshooting"
PLUGIN_DISP_REPORT="Health & Security Report"

SEP_ENABLED_PLUGINS="${SEP_ENABLED_PLUGINS:-schema_change,archive,mysql_backups,checksums}"

AUTOSTART="${AUTOSTART:-0}"
if [ -z "${NO_INTERACTION:-}" ]; then
    is_tty && NO_INTERACTION=0 || NO_INTERACTION=1
fi
SET_CLI_INSTALL_DIR=0
SET_CLI_PLUGINS=0
SET_CLI_PMM=0
HAS_PROMPTED_PMM_AUTH=0

################################################################################
# CLI ARGUMENT PARSING
################################################################################

usage() {
    cat << EOF
SEP Installer

USAGE
  ./sep_installer.sh [OPTIONS]

OPTIONS
  --install-dir DIR        Set installation directory (Default: ~/sep)
  --http-port PORT         Set HTTP port (Default: 8080)
  --https-port PORT        Set HTTPS port (Default: 8444)
  --plugins LIST           Comma-separated list of plugins (internal names)
                           Available: schema_change, archive, mysql_backups, checksums, snippets, mongodb_backups, backup_pg, dipper, alerts, alert_troubleshooting, report
                           Default: schema_change,archive,mysql_backups,checksums
  --create-pmm-container   Create PMM container as part of the stack (Default: No)
  --use-existent-pmm       Use an external/existing PMM instance (removes PMM from stack)
  --pmm-user USER          PMM Username (for PMM 3 Nomad auth)
  --pmm-pass PASS          PMM Password (for PMM 3 Nomad auth)
  --pmm-token TOKEN        PMM Service Account Token (for PMM Inventory Sync)
  --engine ENGINE          Container engine: docker or podman (Default: docker if available, else podman)
  --docker-token TOKEN     Token for registry login if needed
  --autostart              Start the stack automatically after install
  --overwrite              Overwrite existing installation directory without prompting
  --reset-data             Wipe existing SEP data volumes (sep_*) for a clean install.
                           Without it, a re-install over an existing SEP database reuses the
                           prior credentials when available, or stops with guidance otherwise.
  --no-interaction         Skip interactive wizard and use defaults/flags
  --help, -h               Show this help message

ENVIRONMENT
  NO_COLOR                 Suppress all color/styling output (see https://no-color.org/)
  SEP_SERVE_FRONTEND       Serve the React SPA from nginx (Default: 1). Set to 0 to
                           restore the legacy Jinja UI instead.

EXAMPLES
  ./sep_installer.sh --http-port 9090
  ./sep_installer.sh --no-interaction --use-existent-pmm --autostart
EOF
}

parse_args() {
    while [ $# -gt 0 ]; do
        case "$1" in
            --install-dir)
                INSTALL_DIR="$2"
                SET_CLI_INSTALL_DIR=1
                shift 2
                ;;
            --http-port)
                SEP_HTTP_PORT="$2"
                shift 2
                ;;
            --https-port)
                SEP_HTTPS_PORT="$2"
                shift 2
                ;;
            --plugins)
                SEP_ENABLED_PLUGINS="$2"
                SET_CLI_PLUGINS=1
                shift 2
                ;;
            --engine)
                CONTAINER_ENGINE="$2"
                shift 2
                ;;
            --docker-token)
                DOCKER_TOKEN="$2"
                shift 2
                ;;
            --create-pmm-container)
                CREATE_PMM_CONTAINER=1
                SET_CLI_PMM=1
                shift
                ;;
            --use-existent-pmm)
                CREATE_PMM_CONTAINER=0
                SET_CLI_PMM=1
                shift
                ;;
            --pmm-user)
                SEP_PMM_URL_AUTH_ACCOUNT_USER="$2"
                shift 2
                ;;
            --pmm-pass)
                SEP_PMM_URL_AUTH_ACCOUNT_PASS="$2"
                shift 2
                ;;
            --pmm-token)
                SEP_PMM_URL_AUTH_TOKEN="$2"
                shift 2
                ;;
            --autostart)
                AUTOSTART=1
                shift
                ;;
            --overwrite)
                OVERWRITE_INSTALL_DIR=1
                shift
                ;;
            --reset-data)
                RESET_DATA=1
                shift
                ;;
            --no-interaction | --headless | --yes | -y)
                NO_INTERACTION=1
                shift
                ;;
            --help | -h)
                usage
                exit 0
                ;;
            *)
                if [ "${1#-}" != "$1" ]; then
                    echo "Unknown option: $1"
                    exit 1
                fi
                shift
                ;;
        esac
    done
}

################################################################################
# PLUGIN LOGIC
################################################################################

get_display_name() {
    case "$1" in
        schema_change) echo "$PLUGIN_DISP_SCHEMA" ;;
        archive) echo "$PLUGIN_DISP_ARCHIVE" ;;
        mysql_backups) echo "$PLUGIN_DISP_BACKUPS" ;;
        checksums) echo "$PLUGIN_DISP_CHECKSUMS" ;;
        snippets) echo "$PLUGIN_DISP_SNIPPETS" ;;
        mongodb_backups) echo "$PLUGIN_DISP_MONGO" ;;
        backup_pg) echo "$PLUGIN_DISP_BACKUP_PG" ;;
        dipper) echo "$PLUGIN_DISP_DIPPER" ;;
        alerts) echo "$PLUGIN_DISP_ALERTS" ;;
        alert_troubleshooting) echo "$PLUGIN_DISP_ALERT_TROUBLESHOOTING" ;;
        report) echo "$PLUGIN_DISP_REPORT" ;;
        *) echo "$1" ;;
    esac
}

init_plugin_disable_markers() {
    local plugins_to_check=(
        "schema_change"
        "archive"
        "mysql_backups"
        "checksums"
        "snippets"
        "mongodb_backups"
        "backup_pg"
        "dipper"
        "alerts"
        "alert_troubleshooting"
        "report"
    )
    local var_name disable_char

    for plugin in "${plugins_to_check[@]}"; do
        var_name="SEP_PLUGINS_${plugin^^}_DISABLE"
        [[ ",${SEP_ENABLED_PLUGINS}," == *",${plugin},"* ]] && disable_char="" || disable_char="#"
        printf -v "${var_name}" "%s" "${disable_char}"
        export "${var_name?}"
    done
}

################################################################################
# CORE FUNCTIONS
################################################################################

check_prereqs() {
    banner
    local requirements="openssl sed find gunzip ${CONTAINER_ENGINE}"
    if [ "${NO_UI}" -eq 0 ]; then
        run_ui check_prereqs --tools "${requirements}"
    else
        echo "Checking System Requirements..."
        for tool in $requirements; do
            if ! command -v "$tool" > /dev/null 2>&1; then
                echo "Missing: $tool"
                exit 1
            fi
        done
        log_info "All prerequisites met. Using engine: ${CONTAINER_ENGINE}"
    fi
    spin_or_die dots "Checking ${CONTAINER_ENGINE}..." "${CONTAINER_ENGINE} info"
    print_styled "All prerequisites met." -style "bold green"
    log_milestone "Prerequisites verified for ${CONTAINER_ENGINE}"
}

get_user_input() {
    if [ "${NO_UI}" -eq 0 ]; then
        get_user_input_ui
    else
        get_user_input_text
    fi
}

get_user_input_ui() {
    banner

    if [ "$SET_CLI_INSTALL_DIR" -eq 0 ]; then
        local install_dir_file="${TEMP_DIR}/install_dir.txt"
        run_ui input --prompt "Install Directory" --default "$INSTALL_DIR" --output "$install_dir_file"
        INSTALL_DIR=$(cat "$install_dir_file")
        check_install_dir_writable
    fi

    if [ "$SET_CLI_PLUGINS" -eq 0 ]; then
        ALL_PLUGINS_DISP="${PLUGIN_DISP_SCHEMA},${PLUGIN_DISP_ARCHIVE},${PLUGIN_DISP_BACKUPS},${PLUGIN_DISP_CHECKSUMS},${PLUGIN_DISP_SNIPPETS},${PLUGIN_DISP_MONGO},${PLUGIN_DISP_BACKUP_PG},${PLUGIN_DISP_DIPPER},${PLUGIN_DISP_ALERTS},${PLUGIN_DISP_ALERT_TROUBLESHOOTING},${PLUGIN_DISP_REPORT}"

        local plugins_file="${TEMP_DIR}/plugins.txt"
        run_ui choose_plugins --current "$SEP_ENABLED_PLUGINS" --options "$ALL_PLUGINS_DISP" --output "$plugins_file"
        SELECTED_DISP=$(cat "$plugins_file")
        SEP_ENABLED_PLUGINS="$SELECTED_DISP"
    fi

    if [ "$SET_CLI_PMM" -eq 0 ]; then
        if run_ui confirm --default-val "n" "Create PMM Container?"; then
            CREATE_PMM_CONTAINER=1
        else
            CREATE_PMM_CONTAINER=0
        fi
    fi
    if [ "$CREATE_PMM_CONTAINER" -eq 0 ]; then
        run_ui log --level warn "External PMM Configuration"

        local pmm_input_file="${TEMP_DIR}/pmm_input.txt"

        if [ -z "${SEP_PMM_URL_AUTH_ACCOUNT_USER}" ]; then
            run_ui input --prompt "PMM User" --default "admin" --output "$pmm_input_file"
            SEP_PMM_URL_AUTH_ACCOUNT_USER=$(cat "$pmm_input_file")
        fi

        if [ -z "${SEP_PMM_URL_AUTH_ACCOUNT_PASS}" ]; then
            run_ui input --prompt "PMM Password" --password --output "$pmm_input_file"
            SEP_PMM_URL_AUTH_ACCOUNT_PASS=$(cat "$pmm_input_file")
        fi

        if [ -z "${SEP_PMM_URL_AUTH_TOKEN:-}" ]; then
            run_ui input --prompt "Enter PMM Service Account Token" --password --output "$pmm_input_file"
            SEP_PMM_URL_AUTH_TOKEN=$(cat "$pmm_input_file")
        fi

        SEP_PMM_URL_AUTH_ACCOUNT="${SEP_PMM_URL_AUTH_ACCOUNT_USER}:${SEP_PMM_URL_AUTH_ACCOUNT_PASS}"
        export SEP_PMM_URL_AUTH_ACCOUNT SEP_PMM_URL_AUTH_TOKEN

        HAS_PROMPTED_PMM_AUTH=1
    fi
}

get_user_input_text() {
    echo "--- Configuration Wizard ---"

    if [ "$SET_CLI_INSTALL_DIR" -eq 0 ]; then
        read -r -p "Install Directory [${INSTALL_DIR}]: " _input
        if [ -n "$_input" ]; then INSTALL_DIR="$_input"; fi
    fi

    if [ "$SET_CLI_PLUGINS" -eq 0 ]; then
        echo ""
        echo "Available Plugins: schema_change, archive, mysql_backups, checksums, snippets, mongodb_backups, backup_pg, dipper, alerts, alert_troubleshooting, report"
        echo "Current Selection: ${SEP_ENABLED_PLUGINS}"
        read -r -p "Enter plugins list (comma separated) or press Enter to keep current: " _input
        if [ -n "$_input" ]; then SEP_ENABLED_PLUGINS="$_input"; fi
    fi

    if [ "$SET_CLI_PMM" -eq 0 ]; then
        read -r -p "Create PMM Container? [y/N] " _yn
        case "$_yn" in
            [Yy]*) CREATE_PMM_CONTAINER=1 ;;
            *) CREATE_PMM_CONTAINER=0 ;;
        esac
    fi

    if [ "$CREATE_PMM_CONTAINER" -eq 0 ]; then
        echo "--- External PMM Configuration ---"
        if [ -z "${SEP_PMM_URL_AUTH_ACCOUNT_USER}" ]; then
            read -rp "PMM User [admin]: " _input
            SEP_PMM_URL_AUTH_ACCOUNT_USER="${_input:-admin}"
        fi

        if [ -z "${SEP_PMM_URL_AUTH_ACCOUNT_PASS}" ]; then
            read -rsp "PMM Password: " SEP_PMM_URL_AUTH_ACCOUNT_PASS
            echo ""
        fi

        if [ -z "${SEP_PMM_URL_AUTH_TOKEN:-}" ]; then
            read -rsp "PMM Service Account Token: " SEP_PMM_URL_AUTH_TOKEN
            echo ""
        fi
        SEP_PMM_URL_AUTH_ACCOUNT="${SEP_PMM_URL_AUTH_ACCOUNT_USER}:${SEP_PMM_URL_AUTH_ACCOUNT_PASS}"
        export SEP_PMM_URL_AUTH_ACCOUNT SEP_PMM_URL_AUTH_TOKEN
    fi
}

summary_screen() {
    if [ "${NO_UI}" -eq 0 ]; then
        summary_screen_ui
    else
        summary_screen_text
    fi
}

summary_screen_ui() {
    clear_screen
    banner

    if [ "$CREATE_PMM_CONTAINER" -eq 1 ]; then DISP_PMM="Yes"; else DISP_PMM="No"; fi

    JSON_DATA="[
        {\"key\": \"Install Dir\", \"value\": \"${INSTALL_DIR}\"},
        {\"key\": \"Create PMM\", \"value\": \"${DISP_PMM}\"},
        {\"key\": \"Plugins\", \"value\": \"${SEP_ENABLED_PLUGINS}\"},
        {\"key\": \"HTTP Port\", \"value\": \"${SEP_HTTP_PORT}\"},
        {\"key\": \"HTTPS Port\", \"value\": \"${SEP_HTTPS_PORT}\"}
    ]"

    local summary_out="${TEMP_DIR}/summary_result.json"
    run_ui summary --data "$JSON_DATA" --output "$summary_out"

    # shellcheck source=/dev/null
    source "${summary_out}"

    if [ "$CREATE_PMM_CONTAINER" -eq 0 ] && [ "${HAS_PROMPTED_PMM_AUTH}" -eq 0 ]; then
        if [ -z "${SEP_PMM_URL_AUTH_ACCOUNT_USER:-}" ] || [ -z "${SEP_PMM_URL_AUTH_ACCOUNT_PASS:-}" ] || [ -z "${SEP_PMM_URL_AUTH_TOKEN:-}" ]; then
            run_ui log --level warn "PMM set to External, but credentials missing. Please provide them."
            local pmm_input_file="${TEMP_DIR}/pmm_input.txt"

            if [ -z "${SEP_PMM_URL_AUTH_ACCOUNT_USER:-}" ]; then
                run_ui input --prompt "PMM User" --default "admin" --output "$pmm_input_file"
                SEP_PMM_URL_AUTH_ACCOUNT_USER=$(cat "$pmm_input_file")
            fi
            if [ -z "${SEP_PMM_URL_AUTH_ACCOUNT_PASS:-}" ]; then
                run_ui input --prompt "PMM Password" --password --output "$pmm_input_file"
                SEP_PMM_URL_AUTH_ACCOUNT_PASS=$(cat "$pmm_input_file")
            fi
            if [ -z "${SEP_PMM_URL_AUTH_TOKEN:-}" ]; then
                run_ui input --prompt "Enter PMM Service Account Token" --password --output "$pmm_input_file"
                SEP_PMM_URL_AUTH_TOKEN=$(cat "$pmm_input_file")
            fi

            SEP_PMM_URL_AUTH_ACCOUNT="${SEP_PMM_URL_AUTH_ACCOUNT_USER}:${SEP_PMM_URL_AUTH_ACCOUNT_PASS}"
            export SEP_PMM_URL_AUTH_ACCOUNT SEP_PMM_URL_AUTH_TOKEN
        fi
    fi
}

summary_screen_text() {
    clear_screen
    banner
    echo "--- Configuration Summary ---"
    echo "Install Dir: ${INSTALL_DIR}"
    if [ "$CREATE_PMM_CONTAINER" -eq 1 ]; then echo "Create PMM:  Yes"; else echo "Create PMM:  No"; fi
    echo "Plugins:     ${SEP_ENABLED_PLUGINS}"
    echo "HTTP Port:   ${SEP_HTTP_PORT}"
    echo "HTTPS Port:  ${SEP_HTTPS_PORT}"
    echo "-----------------------------"

    read -r -p "Proceed with installation? [Y/n] " _yn
    case "$_yn" in
        [Nn]*)
            exit 1
            ;;
        *) return 0 ;;
    esac
}

generate_tls_cli() {
    local install_dir="$1"
    local cert_list="$2"
    local certs_dir="${install_dir}/certs"
    mkdir -p "${certs_dir}"
    (
        cd "${certs_dir}"
        run_quiet() {
            local err
            if ! err=$("$@" 2>&1 > /dev/null); then
                echo "${err}" >&2
                return 1
            fi
        }

        run_quiet_out() {
            local dest="$1"
            shift
            local err
            if ! err=$("$@" 2>&1 | tee "$dest"); then
                echo "${err}" >&2
                return 1
            fi
        }

        run_quiet_out sep_token_jwt_key.key openssl genpkey -algorithm RSA -pkeyopt rsa_keygen_bits:4096
        run_quiet_out sep_token_jwt_key.pem openssl rsa -pubout -in sep_token_jwt_key.key
        run_quiet_out sep-ca-key.pem openssl ecparam -genkey -name secp384r1 -noout
        run_quiet_out sep-ca.pem openssl req -new -x509 -key sep-ca-key.pem -nodes \
            -sha384 -days 365 -subj "/CN=SEP Root CA" \
            -addext "keyUsage=critical,digitalSignature,keyCertSign" \
            -addext "basicConstraints=critical,CA:true,pathlen:0" \
            -addext "subjectKeyIdentifier=hash" \
            -addext "authorityKeyIdentifier=keyid:always" \
            -addext "extendedKeyUsage=serverAuth,clientAuth"

        local base_conf="[ req ]
distinguished_name = req_distinguished_name
req_extensions = v3_req
[ req_distinguished_name ]
[ v3_req ]
authorityKeyIdentifier = keyid:always,issuer
basicConstraints = critical,CA:FALSE
keyUsage = critical, digitalSignature, keyEncipherment
extendedKeyUsage = serverAuth, clientAuth
subjectAltName = @alt_names
[alt_names]
DNS.1=localhost
DNS.2=sep
DNS.3=*.sep
DNS.4=inventory_api
DNS.5=tasks_api
DNS.6=app
IP.1=127.0.0.1
"

        IFS=',' read -r -a cert_array <<< "${cert_list}"
        for cert in "${cert_array[@]}"; do
            cert="${cert// /}"
            [ -n "${cert}" ] || continue
            printf '%s\n' "${base_conf}" > openssl.conf
            run_quiet_out "${cert}-cert-key.pem" openssl ecparam -genkey -name secp384r1 -noout
            run_quiet_out "${cert}-cert.csr" openssl req -new -key "${cert}-cert-key.pem" -subj "/CN=${cert}"
            run_quiet_out "${cert}-cert.pem" openssl x509 -req -in "${cert}-cert.csr" -CA sep-ca.pem -CAkey sep-ca-key.pem \
                -CAcreateserial -days 365 -sha384 -extfile openssl.conf -extensions v3_req
            rm -f "${cert}-cert.csr" openssl.conf
        done

        run_quiet find "${certs_dir}" -type f -exec chmod 444 {} +
    )
}

render_templates_cli() {
    test "${DEBUG:-0}" = 0 || set -o xtrace
    ABS_INSTALL_DIR="$1"

    local pmm_marker="#---PMM---#"
    local remove_pmm_block_expr="/^${pmm_marker//\//\\/}\$/d"
    if [ "$CREATE_PMM_CONTAINER" -eq 0 ]; then
        remove_pmm_block_expr="/^${pmm_marker//\//\\/}\$/,/^${pmm_marker//\//\\/}\$/d"
    fi

    local frontend_marker="#---FRONTEND---#"
    local no_frontend_marker="#---NO-FRONTEND---#"
    local remove_frontend_block_expr
    local remove_no_frontend_block_expr
    if [ "$SEP_SERVE_FRONTEND" -eq 1 ]; then
        remove_frontend_block_expr="/^${frontend_marker//\//\\/}\$/d"
        remove_no_frontend_block_expr="/^${no_frontend_marker//\//\\/}\$/,/^${no_frontend_marker//\//\\/}\$/d"
    else
        remove_frontend_block_expr="/^${frontend_marker//\//\\/}\$/,/^${frontend_marker//\//\\/}\$/d"
        remove_no_frontend_block_expr="/^${no_frontend_marker//\//\\/}\$/d"
    fi

    for file_var in "CASDOOR_INIT_JSON_DATA:${ABS_INSTALL_DIR}/casdoor_init.json" \
        "NGINX_CONFIG:${ABS_INSTALL_DIR}/nginx.conf" \
        "SEP_COMPOSE_YAML:${ABS_INSTALL_DIR}/compose.yaml" \
        "SEP_SETTINGS_YAML:${ABS_INSTALL_DIR}/settings.yaml"; do

        data_var_name="${file_var%%:*}"
        outfile="${file_var#*:}"

        printf '%s' "${!data_var_name}" | base64 -d | gunzip > "${outfile}.tmp"

        case "${outfile}" in
            "${ABS_INSTALL_DIR}/compose.yaml")
                if [ "${DEFAULT_CONTAINER_REGISTRY}/" != "docker.io/" ]; then
                    sed -i "s^docker.io/^${DEFAULT_CONTAINER_REGISTRY}/^g" "${outfile}.tmp"
                fi
                ;;
        esac

        sed \
            -e "s|\${SEP_HTTP_PORT}|${SEP_HTTP_PORT}|g" \
            -e "s|\${SEP_HTTPS_PORT}|${SEP_HTTPS_PORT}|g" \
            -e "s|\${INSTALL_DIR}|${ABS_INSTALL_DIR}|g" \
            -e "s|\${SEP_PMM_PUBLIC_HOST}|${SEP_PMM_PUBLIC_HOST}|g" \
            -e "s|\${SEP_PMM_PUBLIC_ADDRESS}|${SEP_PMM_PUBLIC_HOST}|g" \
            -e "s|\${SEP_PMM_PORT}|${SEP_PMM_PORT}|g" \
            -e "s|\${SEP_PMM_FRONTEND}|${SEP_PMM_FRONTEND}|g" \
            -e "s|\${SEP_PMM_URL_AUTH_TOKEN}|${SEP_PMM_URL_AUTH_TOKEN}|g" \
            -e "s|\${SEP_PMM_URL_AUTH_ACCOUNT}|${SEP_PMM_URL_AUTH_ACCOUNT}|g" \
            -e "s|\${SEP_IMAGE_NAME}|${SEP_IMAGE_NAME}|g" \
            -e "s|\${SEP_IMAGE_TAG}|${SEP_IMAGE_TAG}|g" \
            -e "s|\${CASDOOR_SEP_CLIENT_ID}|${CASDOOR_SEP_CLIENT_ID}|g" \
            -e "s|\${CASDOOR_SEP_CLIENT_SECRET}|${CASDOOR_SEP_CLIENT_SECRET}|g" \
            -e "s|\${SEP_BACKEND_DB_PASSWORD}|${SEP_BACKEND_DB_PASSWORD}|g" \
            -e "s|\${SEP_REDIS_PASSWORD}|${SEP_REDIS_PASSWORD}|g" \
            -e "s|\${CASDOOR_DEFAULT_ORG_SALT}|${CASDOOR_DEFAULT_ORG_SALT}|g" \
            -e "s|\${CASDOOR_SEP_ORG_SALT}|${CASDOOR_SEP_ORG_SALT}|g" \
            -e "s|\${CASDOOR_DEFAULT_CLIENT_SECRET}|${CASDOOR_DEFAULT_CLIENT_SECRET}|g" \
            -e "s|\${CASDOOR_DEFAULT_CLIENT_ID}|${CASDOOR_DEFAULT_CLIENT_ID}|g" \
            -e "s|\${CASDOOR_DEFAULT_ADMIN_PASSWD}|${CASDOOR_DEFAULT_ADMIN_PASSWD}|g" \
            -e "s|\${CASDOOR_SEP_ADMIN_PASSWD}|${CASDOOR_SEP_ADMIN_PASSWD}|g" \
            -e "s|\${CASDOOR_SEP_SEP_PASSWD}|${CASDOOR_SEP_SEP_PASSWD}|g" \
            -e "s|\${SEP_CASDOOR_CERTIFICATE_JSON}|${SEP_CASDOOR_CERTIFICATE_JSON}|g" \
            -e "s|\${SEP_CASDOOR_PRIVATE_KEY_JSON}|${SEP_CASDOOR_PRIVATE_KEY_JSON}|g" \
            -e "s|\${SEP_PLUGINS_SCHEMA_CHANGE_DISABLE}|${SEP_PLUGINS_SCHEMA_CHANGE_DISABLE}|g" \
            -e "s|\${SEP_PLUGINS_ARCHIVE_DISABLE}|${SEP_PLUGINS_ARCHIVE_DISABLE}|g" \
            -e "s|\${SEP_PLUGINS_MYSQL_BACKUPS_DISABLE}|${SEP_PLUGINS_MYSQL_BACKUPS_DISABLE}|g" \
            -e "s|\${SEP_PLUGINS_CHECKSUMS_DISABLE}|${SEP_PLUGINS_CHECKSUMS_DISABLE}|g" \
            -e "s|\${SEP_PLUGINS_SNIPPETS_DISABLE}|${SEP_PLUGINS_SNIPPETS_DISABLE}|g" \
            -e "s|\${SEP_PLUGINS_MONGODB_BACKUPS_DISABLE}|${SEP_PLUGINS_MONGODB_BACKUPS_DISABLE}|g" \
            -e "s|\${SEP_PLUGINS_BACKUP_PG_DISABLE}|${SEP_PLUGINS_BACKUP_PG_DISABLE}|g" \
            -e "s|\${SEP_PLUGINS_DIPPER_DISABLE}|${SEP_PLUGINS_DIPPER_DISABLE}|g" \
            -e "s|\${SEP_PLUGINS_ALERTS_DISABLE}|${SEP_PLUGINS_ALERTS_DISABLE}|g" \
            -e "s|\${SEP_PLUGINS_ALERT_TROUBLESHOOTING_DISABLE}|${SEP_PLUGINS_ALERT_TROUBLESHOOTING_DISABLE}|g" \
            -e "s|\${SEP_PLUGINS_REPORT_DISABLE}|${SEP_PLUGINS_REPORT_DISABLE}|g" \
            -e "s|\${SEP_INTERNAL_TOKEN}|${SEP_INTERNAL_TOKEN}|g" \
            -e "${remove_pmm_block_expr}" \
            -e "${remove_frontend_block_expr}" \
            -e "${remove_no_frontend_block_expr}" \
            "${outfile}.tmp" > "${outfile}"

        if grep -qE '^[[:space:]]*#---(PMM|FRONTEND|NO-FRONTEND)---#[[:space:]]*$' "${outfile}"; then
            log_err "Template rendering left unprocessed marker lines in ${outfile}"
            exit 1
        fi

        rm -f "${outfile}.tmp"
    done
}

data_volume_exists() {
    "${CONTAINER_ENGINE}" volume ls -q 2> /dev/null | grep -qx "$1"
}

secrets_reusable() {
    [ -f "${INSTALL_DIR}/.secrets" ] || return 1
    [ -f "${INSTALL_DIR}/certs/sep_token_jwt_key.key" ] || return 1
    [ -f "${INSTALL_DIR}/certs/sep_token_jwt_key.pem" ] || return 1
    local pw=""
    pw=$(grep -E '^SEP_BACKEND_DB_PASSWORD=' "${INSTALL_DIR}/.secrets" | cut -d= -f2-) || true
    [ -n "${pw}" ]
}

load_existing_secrets_and_certs() {
    local saved_install_dir="${INSTALL_DIR}"
    # PMM credentials are not tied to the data volumes, so explicitly provided
    # values take precedence over the ones reused from .secrets.
    local provided_pmm_user="${SEP_PMM_URL_AUTH_ACCOUNT_USER}"
    local provided_pmm_pass="${SEP_PMM_URL_AUTH_ACCOUNT_PASS}"
    local provided_pmm_token="${SEP_PMM_URL_AUTH_TOKEN:-}"

    local line key value
    while IFS= read -r line || [ -n "${line}" ]; do
        case "${line}" in
            "" | \#*) continue ;;
        esac
        key=${line%%=*}
        value=${line#*=}
        case "${key}" in
            CASDOOR_DEFAULT_ORG_SALT | CASDOOR_SEP_ORG_SALT | CASDOOR_DEFAULT_CLIENT_ID | CASDOOR_DEFAULT_CLIENT_SECRET | CASDOOR_SEP_CLIENT_ID | CASDOOR_SEP_CLIENT_SECRET | CASDOOR_DEFAULT_ADMIN_PASSWD | CASDOOR_SEP_ADMIN_PASSWD | CASDOOR_SEP_SEP_PASSWD | SEP_BACKEND_DB_PASSWORD | SEP_REDIS_PASSWORD | SEP_INTERNAL_TOKEN | SEP_PMM_URL_AUTH_ACCOUNT | SEP_PMM_URL_AUTH_TOKEN | GF_SECURITY_ADMIN_PASSWORD | INSTALL_DIR)
                declare -gx "${key}=${value}"
                ;;
        esac
    done < "${INSTALL_DIR}/.secrets"

    INSTALL_DIR="${saved_install_dir}"
    FINAL_INSTALL_DIR="${saved_install_dir}"

    if [ -n "${provided_pmm_user}" ] || [ -n "${provided_pmm_pass}" ]; then
        SEP_PMM_URL_AUTH_ACCOUNT="${provided_pmm_user:-admin}:${provided_pmm_pass:-admin}"
    fi
    if [ -n "${provided_pmm_token}" ]; then
        SEP_PMM_URL_AUTH_TOKEN="${provided_pmm_token}"
    fi

    export INSTALL_DIR FINAL_INSTALL_DIR SEP_PMM_URL_AUTH_ACCOUNT SEP_PMM_URL_AUTH_TOKEN
    cp -rf "${saved_install_dir}/certs" "${ATOMIC_DIR}/certs"
}

wipe_data_volumes() {
    local lbl
    for lbl in "com.docker.compose.project=sep" "io.podman.compose.project=sep"; do
        "${CONTAINER_ENGINE}" ps -aq --filter "label=${lbl}" 2> /dev/null |
            xargs -r "${CONTAINER_ENGINE}" rm -f > /dev/null 2>&1 || true
    done
    "${CONTAINER_ENGINE}" volume ls -q 2> /dev/null | grep '^sep_' |
        xargs -r "${CONTAINER_ENGINE}" volume rm > /dev/null 2>&1 || true
}

resolve_data_strategy() {
    DATA_STRATEGY="fresh"
    data_volume_exists "sep_sep-data" || return 0

    if [ "${RESET_DATA}" -eq 1 ]; then
        log_info "Wiping existing SEP data volumes for a clean install (--reset-data)..."
        wipe_data_volumes
        return 0
    fi

    if secrets_reusable; then
        DATA_STRATEGY="reuse"
        log_info "Existing SEP database found; reusing credentials from ${INSTALL_DIR}."
        return 0
    fi

    local msg="Existing SEP data volumes were found (project 'sep'), but no matching credentials in '${INSTALL_DIR}'.
A fresh install would generate new credentials that do not match the existing database, causing authentication failures.
Re-run with --install-dir pointing at the original install to reuse its credentials, or pass --reset-data to wipe the existing data for a clean install."

    if [ "${NO_INTERACTION}" -eq 1 ]; then
        log_err "${msg}"
        exit 1
    fi

    log_warn "${msg}"
    if [ "${NO_UI}" -eq 0 ]; then
        if run_ui confirm --default-val "n" "Wipe existing SEP data volumes and perform a clean install?"; then
            wipe_data_volumes
        else
            log_err "Installation aborted to protect existing data."
            exit 0
        fi
    else
        read -r -p "Wipe existing SEP data volumes and perform a clean install? [y/N] " _yn
        case "${_yn}" in
            [Yy]*) wipe_data_volumes ;;
            *)
                log_err "Installation aborted to protect existing data."
                exit 0
                ;;
        esac
    fi
}

generate_secrets_and_render() {
    ATOMIC_DIR=$(mktemp -d)

    if [ "${DATA_STRATEGY:-fresh}" = "reuse" ]; then
        load_existing_secrets_and_certs
        log_milestone "Reusing existing credentials and certificates"
    else
        set -a
        CASDOOR_DEFAULT_ORG_SALT=$(openssl rand -hex 8)
        CASDOOR_SEP_ORG_SALT=$(openssl rand -hex 8)
        CASDOOR_DEFAULT_CLIENT_ID=$(openssl rand -hex 10)
        CASDOOR_DEFAULT_CLIENT_SECRET=$(openssl rand -hex 20)
        CASDOOR_SEP_CLIENT_ID=$(openssl rand -hex 10)
        CASDOOR_SEP_CLIENT_SECRET=$(openssl rand -hex 20)
        CASDOOR_DEFAULT_ADMIN_PASSWD=$(openssl rand -hex 20)
        CASDOOR_SEP_ADMIN_PASSWD=$(openssl rand -hex 20)
        CASDOOR_SEP_SEP_PASSWD=$(openssl rand -hex 20)
        SEP_BACKEND_DB_PASSWORD=$(openssl rand -hex 20)
        SEP_REDIS_PASSWORD=$(openssl rand -hex 20)
        SEP_INTERNAL_TOKEN=$(openssl rand -hex 32)
        SEP_PMM_URL_AUTH_ACCOUNT=${SEP_PMM_URL_AUTH_ACCOUNT:-admin:admin}
        SEP_PMM_URL_AUTH_TOKEN=${SEP_PMM_URL_AUTH_TOKEN:-CHANGEME}
        GF_SECURITY_ADMIN_PASSWORD=$(openssl rand -hex 20)
        FINAL_INSTALL_DIR="${INSTALL_DIR}"
        set +a

        if [ "${NO_UI}" -eq 0 ]; then
            run_ui generate_tls --install-dir "${ATOMIC_DIR}" --cert-list "${CERTLIST}"
        else
            echo "Generating TLS (Text Mode)..."
            generate_tls_cli "${ATOMIC_DIR}" "${CERTLIST}"
        fi
        log_milestone "Certificates generated"
    fi

    SEP_CASDOOR_PRIVATE_KEY_JSON=$(sed -z 's/\n/\\\\n/g' "${ATOMIC_DIR}/certs/sep_token_jwt_key.key")
    SEP_CASDOOR_CERTIFICATE_JSON=$(sed -z 's/\n/\\\\n/g' "${ATOMIC_DIR}/certs/sep_token_jwt_key.pem")
    export SEP_CASDOOR_PRIVATE_KEY_JSON SEP_CASDOOR_CERTIFICATE_JSON FINAL_INSTALL_DIR

    touch "${ATOMIC_DIR}/.secrets"
    chmod 640 "${ATOMIC_DIR}/.secrets"

    cat << EOF > "${ATOMIC_DIR}/.secrets"
CASDOOR_DEFAULT_ORG_SALT=${CASDOOR_DEFAULT_ORG_SALT}
CASDOOR_SEP_ORG_SALT=${CASDOOR_SEP_ORG_SALT}
CASDOOR_DEFAULT_CLIENT_ID=${CASDOOR_DEFAULT_CLIENT_ID}
CASDOOR_DEFAULT_CLIENT_SECRET=${CASDOOR_DEFAULT_CLIENT_SECRET}
CASDOOR_SEP_CLIENT_ID=${CASDOOR_SEP_CLIENT_ID}
CASDOOR_SEP_CLIENT_SECRET=${CASDOOR_SEP_CLIENT_SECRET}
CASDOOR_DEFAULT_ADMIN_PASSWD=${CASDOOR_DEFAULT_ADMIN_PASSWD}
CASDOOR_SEP_ADMIN_PASSWD=${CASDOOR_SEP_ADMIN_PASSWD}
CASDOOR_SEP_SEP_PASSWD=${CASDOOR_SEP_SEP_PASSWD}
SEP_BACKEND_DB_PASSWORD=${SEP_BACKEND_DB_PASSWORD}
SEP_REDIS_PASSWORD=${SEP_REDIS_PASSWORD}
SEP_INTERNAL_TOKEN=${SEP_INTERNAL_TOKEN}
SEP_PMM_URL_AUTH_ACCOUNT=${SEP_PMM_URL_AUTH_ACCOUNT}
SEP_PMM_URL_AUTH_TOKEN=${SEP_PMM_URL_AUTH_TOKEN}
GF_SECURITY_ADMIN_PASSWORD=${GF_SECURITY_ADMIN_PASSWORD}
INSTALL_DIR=${INSTALL_DIR}
EOF
    log_milestone "Secrets generated"

    export SEP_HTTP_PORT SEP_HTTPS_PORT SEP_PMM_PUBLIC_HOST SEP_PMM_PORT SEP_PMM_FRONTEND SEP_IMAGE_NAME SEP_IMAGE_TAG CREATE_PMM_CONTAINER SEP_SERVE_FRONTEND
    export CASDOOR_INIT_JSON_DATA NGINX_CONFIG SEP_COMPOSE_YAML SEP_SETTINGS_YAML

    if [ "${NO_UI}" -eq 0 ]; then
        run_ui render_templates --install-dir "${ATOMIC_DIR}"
    else
        render_templates_cli "${ATOMIC_DIR}"
    fi
    log_milestone "Templates rendered"
}

commit_files() {
    if [ ! -d "$ATOMIC_DIR" ]; then
        log_err "Atomic directory missing. Installation failed."
        exit 1
    fi

    if [ ! -d "$INSTALL_DIR" ]; then
        mkdir -p "$INSTALL_DIR"
    fi

    cp -rf "$ATOMIC_DIR"/* "$INSTALL_DIR/"
    cp -rf "$ATOMIC_DIR"/.secrets "$INSTALL_DIR/" 2> /dev/null || true

    log_milestone "Files committed to $INSTALL_DIR"
}

get_engine_command() {
    case "${CONTAINER_ENGINE}" in
        docker)
            echo "docker compose --file ${INSTALL_DIR}/compose.yaml --project-name sep"
            ;;
        podman)
            echo "podman-compose --file ${INSTALL_DIR}/compose.yaml --project-name sep"
            ;;
    esac
}

pull_and_start() {
    CMD=$(get_engine_command)
    local image_ref="${SEP_IMAGE_NAME}:${SEP_IMAGE_TAG}"
    local pulled_image=0

    if [ "${SEP_IMAGE_NAME%%/*}" = "docker.io" ] && [ "${SEP_IMAGE_NAME}" != "docker.io/library/*" ]; then
        if ! check_cmd_silent "${CONTAINER_ENGINE} pull ${image_ref}"; then
            log_info "Public pull failed. Trying to log in..."

            if [ "$NO_INTERACTION" -eq 1 ] && [ -z "${DOCKER_TOKEN}" ]; then
                log_err "Image pull failed and interaction is disabled."
                exit 1
            fi

            EXTRA_ARGS=
            PODMAN_AUTH_FILE=".docker-io-percona-sep"
            SHOULD_DELETE_PODMAN_AUTH_FILE=0
            if [ "${CONTAINER_ENGINE}" = "podman" ]; then
                SHOULD_DELETE_PODMAN_AUTH_FILE=$([ -e "$PODMAN_AUTH_FILE" ] && echo 0 || echo 1)
                EXTRA_ARGS="--authfile=${PODMAN_AUTH_FILE}"
            fi
            if [ -z "${DOCKER_TOKEN}" ]; then
                if [ "${NO_UI}" -eq 0 ]; then
                    local token_file="${TEMP_DIR}/docker_token.txt"
                    run_ui input --prompt "Docker Token" --password --output "$token_file"
                    DOCKER_TOKEN=$(cat "$token_file")
                else
                    read -rsp "Docker Token: " DOCKER_TOKEN
                    echo ""
                fi
            fi

            echo "Logging in..."
            if ! login_output=$(echo "${DOCKER_TOKEN}" | ${CONTAINER_ENGINE} login --username percona ${EXTRA_ARGS:+$EXTRA_ARGS} --password-stdin "${SEP_IMAGE_NAME%%/*}" 2>&1); then
                log_err "Registry login failed."
                [ -n "${login_output}" ] && echo "${login_output}" >&2
                exit 1
            fi
            print_styled "✓ Authenticated to ${SEP_IMAGE_NAME%%/*}" --style "green"

            spin_or_die earth "Pulling SEP image (authenticated)..." "${CONTAINER_ENGINE} pull ${EXTRA_ARGS:+$EXTRA_ARGS} ${image_ref}"
            pulled_image=1
            ${CONTAINER_ENGINE} logout ${EXTRA_ARGS:+$EXTRA_ARGS} docker.io > /dev/null 2>&1 || true
            ${CONTAINER_ENGINE} logout ${EXTRA_ARGS:+$EXTRA_ARGS} https://index.docker.io/v1/ > /dev/null 2>&1 || true
            if [ "$SHOULD_DELETE_PODMAN_AUTH_FILE" -eq 1 ] && [ -e "$PODMAN_AUTH_FILE" ]; then
                rm -f "$PODMAN_AUTH_FILE"
            fi
        else
            pulled_image=1
        fi
    else
        spin_or_die earth "Pulling SEP image..." "${CONTAINER_ENGINE} pull ${image_ref}"
        pulled_image=1
    fi
    if [ "$pulled_image" -eq 1 ]; then
        log_milestone "Image pulled: ${image_ref}"
    fi

    spin_or_die dots "Creating containers..." "${CMD} up --detach --no-start --remove-orphans"
    log_milestone "Containers created"

    if [ "$AUTOSTART" -eq 1 ]; then
        spin_or_die dots "Starting Stack..." "${CMD} start"
        banner
        print_styled "${MILESTONE_LOGS}" --style "bold white"
        echo
        if [ "${NO_UI}" -eq 0 ]; then
            run_ui success_msg "**Installation Complete: SEP started!**

To watch logs, run:
\`\`\`bash
${CMD} logs -f
\`\`\`

To stop the stack, run:
\`\`\`bash
${CMD} down
\`\`\`
"
        else
            echo "Installation Complete: SEP started!"
            echo "To watch logs, run: ${CMD} logs -f"
            echo "To stop the stack, run: ${CMD} down"
        fi
    else
        banner
        print_styled "${MILESTONE_LOGS}" --style "bold white"
        echo
        if [ "${NO_UI}" -eq 0 ]; then
            run_ui success_msg "**Installation Complete!**

To start the stack, run:
\`\`\`bash
${CMD} start
\`\`\`

To watch logs, run:
\`\`\`bash
${CMD} logs -f
\`\`\`
"
        else
            echo "Installation Complete!"
            echo "To start the stack, run: ${CMD} start"
            echo "To watch logs, run: ${CMD} logs -f"
        fi
    fi

    echo ""
    if [ "${NO_UI}" -eq 0 ]; then
        run_ui print_md "
# SEP Access & Credentials
Access Interface: **https://localhost:${SEP_HTTPS_PORT}**

Credentials stored in: \`${INSTALL_DIR}/.secrets\`

Run the following to retrieve your passwords:
"
        print_styled "Admin User (admin)" --style "bold cyan" --justify center
        run_ui print_md "\`\`\`bash
sed -n 's/^CASDOOR_SEP_ADMIN_PASSWD=//p' \"${INSTALL_DIR}/.secrets\"
\`\`\`"
        print_styled "Standard User (sep)" --style "bold cyan" --justify center
        run_ui print_md "\`\`\`bash
sed -n 's/^CASDOOR_SEP_SEP_PASSWD=//p' \"${INSTALL_DIR}/.secrets\"
\`\`\`"
    else
        echo "=============================="
        echo "   SEP Access & Credentials   "
        echo "=============================="
        echo ""
        echo "Access Interface: https://localhost:${SEP_HTTPS_PORT}"
        echo ""
        echo "Credentials stored in: '${INSTALL_DIR}/.secrets"
        echo "Run the following to retrieve your passwords:"
        echo
        echo "Admin User (admin):"
        echo "sed -n 's/^CASDOOR_SEP_ADMIN_PASSWD=//p' \"${INSTALL_DIR}/.secrets\""
        echo "Standard User (sep):"
        echo "sed -n 's/^CASDOOR_SEP_SEP_PASSWD=//p' \"${INSTALL_DIR}/.secrets\""
    fi
}

check_install_dir_writable() {
    local target="$INSTALL_DIR"
    if [ -d "$target" ]; then
        if [ ! -w "$target" ]; then
            log_err "Installation directory '$target' is not writable."
            exit 1
        fi
        return 0
    fi

    local parent_dir
    parent_dir=$(dirname "$target")
    if [ ! -d "$parent_dir" ] || [ ! -w "$parent_dir" ]; then
        log_err "Parent directory '$parent_dir' does not exist or is not writable."
        exit 1
    fi
}

################################################################################
# MAIN EXECUTION
################################################################################

main() {
    parse_args "$@"

    if ! ensure_ui; then
        NO_UI=1
        echo ""
        echo "!!! TEXTUAL UI could not be loaded or was disabled. !!!"
        echo "!!! Running in standard text mode.                  !!!"
        echo ""
        sleep 2
    fi

    check_prereqs
    check_install_dir_writable

    if [ "$NO_INTERACTION" -eq 0 ]; then
        MISSING_PMM_CREDS=0
        [ "$CREATE_PMM_CONTAINER" -eq 0 ] && { [ -z "${SEP_PMM_URL_AUTH_ACCOUNT_USER}" ] || [ -z "${SEP_PMM_URL_AUTH_ACCOUNT_PASS}" ] || [ -z "${SEP_PMM_URL_AUTH_TOKEN:-}" ]; } && MISSING_PMM_CREDS=1

        if [ "$SET_CLI_INSTALL_DIR" -eq 0 ] ||
            [ "$SET_CLI_PLUGINS" -eq 0 ] ||
            [ "$SET_CLI_PMM" -eq 0 ] ||
            [ "$MISSING_PMM_CREDS" -eq 1 ]; then
            get_user_input
        fi

        summary_screen
    else
        if [ "$CREATE_PMM_CONTAINER" -eq 0 ]; then
            SEP_PMM_URL_AUTH_ACCOUNT="${SEP_PMM_URL_AUTH_ACCOUNT_USER:-admin}:${SEP_PMM_URL_AUTH_ACCOUNT_PASS:-admin}"
            export SEP_PMM_URL_AUTH_ACCOUNT
        fi
    fi
    check_install_dir_writable
    log_milestone "Install directory validated"

    resolve_data_strategy

    if [ -d "${INSTALL_DIR}" ] && [ "$(ls -A "${INSTALL_DIR}")" ] && [ "${DATA_STRATEGY}" != "reuse" ]; then
        if [ "$NO_INTERACTION" -eq 0 ] && [ "$OVERWRITE_INSTALL_DIR" -eq 0 ]; then
            if [ "${NO_UI}" -eq 0 ]; then
                log_warn "Installation directory '${INSTALL_DIR}' already exists and is not empty."
                if ! run_ui confirm --default-val "n" "Proceed anyway? (Existing files may be overwritten)"; then
                    log_err "Installation aborted by user."
                    exit 0
                fi
            else
                echo "Warning: Installation directory '${INSTALL_DIR}' already exists and is not empty."
                read -r -p "Proceed anyway? [y/N] " _yn
                case "$_yn" in
                    [Yy]*) ;;
                    *) exit 0 ;;
                esac
            fi
        fi
    fi

    init_plugin_disable_markers
    generate_secrets_and_render
    commit_files
    pull_and_start
}

